int sense_voice_audio_preprocess(float *pcmdata_f, int frames_num, int model_in_n_samples, float** output, int* output_len)
{
    int ret;
    std::vector<float> ori_audio_data(pcmdata_f, pcmdata_f + frames_num);
    std::vector<float> audio_data(model_in_n_samples);
    pad_or_trim(ori_audio_data, audio_data, frames_num, model_in_n_samples);

    knf::FbankOptions opts_;
    opts_.frame_opts.dither = 1.0;
    opts_.frame_opts.snip_edges = true;
    opts_.frame_opts.samp_freq = 16000;
    opts_.frame_opts.frame_shift_ms = 10;
    opts_.frame_opts.frame_length_ms = 25;
    opts_.frame_opts.remove_dc_offset = 1;
    opts_.frame_opts.window_type = "hamming";
    opts_.mel_opts.num_bins = 80;
    opts_.mel_opts.high_freq = 0;
    opts_.mel_opts.low_freq = 20;
    knf::OnlineFbank* fbank = new knf::OnlineFbank(opts_);

    std::vector<float> buf(audio_data.size());
    for (int32_t i = 0; i != audio_data.size(); ++i) {
        buf[i] = audio_data[i] * 32768;
    }
    int32_t start_index = fbank->NumFramesReady();
    fbank->AcceptWaveform(SAMPLE_RATE, buf.data(), audio_data.size());
    fbank->InputFinished();

    int32_t n = fbank->NumFramesReady();
    int32_t new_feature_len = n - start_index;

    int32_t feature_dim = 80;
    std::vector<float> features(new_feature_len * feature_dim);
    float *p = features.data();
    for (int32_t i = 0; i != new_feature_len; ++i) {
      const float *f = fbank->GetFrame(i + start_index);
      std::copy(f, f + feature_dim, p);
      p += feature_dim;
    }

    std::vector<float> f = apply_lfr(features);
    apply_cmvn(&f);

    *output_len = f.size();
    *output = new float[f.size()];
    std::copy(f.begin(), f.end(), *output);

    delete fbank;
    return 0;
}


std::vector<float> apply_lfr(const std::vector<float>& in)
{
    int32_t lfr_window_size = 7;
    int32_t lfr_window_shift = 6;
    int32_t in_feat_dim = 80;

    int32_t in_num_frames = in.size() / in_feat_dim;
    int32_t out_num_frames = (in_num_frames - lfr_window_size) / lfr_window_shift + 1;
    if (in_num_frames < lfr_window_size) {
        lfr_window_size = in_num_frames;
    }
    int32_t out_feat_dim = in_feat_dim * lfr_window_size;

    std::vector<float> out(out_num_frames * out_feat_dim);

    const float* p_in = in.data();
    float* p_out = out.data();

    for (int32_t i = 0; i != out_num_frames; ++i) {
        std::copy(p_in, p_in + out_feat_dim, p_out);

        p_out += out_feat_dim;
        p_in += lfr_window_shift * in_feat_dim;
    }

    return out;
}

