int argmax(float *array)
{
    int start_index = 0;
    int max_index = 0;
    float max_value = array[0];
    for (int i = start_index + 1; i < VOCAB_NUM; i++)
    {
        if (array[i] > max_value)
        {
            max_value = array[i];
            max_index = i;
        }
    }
    return max_index;
}

void replace_substr(std::string &str, const std::string &from, const std::string &to)
{
    if (from.empty())
        return; // Prevent infinite loop if 'from' is empty
    size_t start_pos = 0;
    while ((start_pos = str.find(from, start_pos)) != std::string::npos)
    {
        str.replace(start_pos, from.length(), to);
        start_pos += to.length(); // Advance position by length of the replacement
    }
}

int read_vocab(const char* vocab_path, VocabEntry *vocab)
{
    FILE *fp;
    char line[512];

    fp = fopen(vocab_path, "r");
    if (fp == NULL)
    {
        perror("Error opening file");
        return -1;
    }

    int count = 0;
    while (fgets(line, sizeof(line), fp))
    {
        // 查找最后一个空格
        char* space = strrchr(line, ' ');
        if (space == NULL) {
            printf("error: space is NULL\n");
            return -1;
        }

        *space = '\0';  // 把空格替换为字符串结束符，这样 line 变成 token
        vocab[count].token = strdup(line);  // token

        vocab[count].index = atoi(space + 1);  // index

        // 去除换行符（如果存在）
        char* newline = strchr(vocab[count].token, '\n');
        if (newline) *newline = '\0';

        count++;
    }

    fclose(fp);

    return 0;
}

void pad_or_trim(const std::vector<float> &array, std::vector<float> &result, int array_shape, int length)
{

    if (array_shape > length)
    {
        std::copy(array.begin(), array.begin() + length, result.begin());
    }
    else
    {
        std::copy(array.begin(), array.end(), result.begin());
        std::fill(result.begin() + array_shape, result.end(), 0.0f);
    }
}

int read_lines(const char *fileName, float *data, int max_lines)
{

    FILE *file;
    int line_count = 0;

    file = fopen(fileName, "r");
    if (file == NULL)
    {
        printf("Error opening file %s\n",fileName);
        return -1;
    }

    while (line_count < max_lines && fscanf(file, "%f", &data[line_count]) == 1)
    {
        line_count++;
    }

    fclose(file);

    return 0;
}

std::vector<float16> fp32_array_to_fp16(const float* src, size_t len)
{
    std::vector<float16> dst(len);
    for (size_t i = 0; i < len; ++i)
    {
        dst[i] = fp32_to_fp16(src[i]);
    }
    return dst;
}

std::vector<float> fp16_array_to_fp32(const float16* src, size_t len)
{
    std::vector<float> dst(len);
    for (size_t i = 0; i < len; ++i)
    {
        dst[i] = fp16_to_fp32(src[i]);
    }
    return dst;    
}